using System.Reflection;
using System.Text;
using InertiaCore.TypeGen.Internal;

namespace InertiaCore.TypeGen;

/// <summary>
/// Generates a TypeScript declaration file describing the props of every
/// <c>[InertiaPage]</c> type in a compiled assembly and the types those props reference.
/// Reads the assembly with a <see cref="MetadataLoadContext"/> so user code is never
/// executed.
/// </summary>
public sealed class TypeScriptDeclarationGenerator
{
    private const string Header =
        "// <auto-generated />\n" +
        "// Generated by InertiaCore.TypeGen. Do not edit this file manually.\n" +
        "// Re-run the generator to refresh it.\n";

    private const string SharedPropsInterfaceName = "InertiaSharedProps";

    /// <summary>
    /// Generates the declaration content for the assembly described by
    /// <paramref name="options"/>.
    /// </summary>
    /// <param name="options">The generation options.</param>
    /// <returns>The generated content and any diagnostics.</returns>
    /// <exception cref="ArgumentException">
    /// <see cref="TypeScriptGeneratorOptions.AssemblyPath"/> is missing or the file does not exist.
    /// </exception>
    public GenerationResult Generate(TypeScriptGeneratorOptions options)
    {
        ArgumentNullException.ThrowIfNull(options);

        if (string.IsNullOrWhiteSpace(options.AssemblyPath))
        {
            throw new ArgumentException("AssemblyPath is required.", nameof(options));
        }

        string assemblyPath = Path.GetFullPath(options.AssemblyPath);
        if (!File.Exists(assemblyPath))
        {
            throw new ArgumentException($"Assembly '{assemblyPath}' does not exist.", nameof(options));
        }

        var diagnostics = new List<GenerationDiagnostic>();
        IReadOnlyList<PageEntry> pages;

        string content;
        using (var context = new MetadataLoadContext(new PathAssemblyResolver(BuildResolverPaths(assemblyPath, options.ReferencePaths))))
        {
            Assembly assembly = context.LoadFromAssemblyPath(assemblyPath);
            pages = DiscoverPages(assembly);
            content = GenerateContent(assembly, pages, options, diagnostics);
        }

        return new GenerationResult
        {
            Content = content,
            Diagnostics = diagnostics,
            PageCount = pages.Count,
        };
    }

    private static string GenerateContent(
        Assembly assembly,
        IReadOnlyList<PageEntry> pages,
        TypeScriptGeneratorOptions options,
        List<GenerationDiagnostic> diagnostics)
    {
        var resolver = new TypeNameResolver();
        var mapper = new TypeMapper(resolver, options, assembly, diagnostics);

        Type? sharedPropsType = DiscoverSharedProps(assembly, diagnostics);
        if (sharedPropsType is not null)
        {
            resolver.Pin(sharedPropsType, SharedPropsInterfaceName);
        }

        var distinctTypes = pages
            .Select(p => p.Type)
            .Distinct()
            .OrderBy(FullNameOf, StringComparer.Ordinal)
            .ToList();

        foreach (Type type in distinctTypes)
        {
            resolver.Reserve(type);
        }

        var interfaces = new Dictionary<string, string>(StringComparer.Ordinal);
        for (int i = 0; i < resolver.Queue.Count; i++)
        {
            Type type = resolver.Queue[i];
            string name = resolver.Reserve(type);
            if (interfaces.ContainsKey(name))
            {
                continue;
            }

            try
            {
                interfaces[name] = mapper.RenderInterface(type, name);
            }
            catch (Exception ex)
            {
                diagnostics.Add(new GenerationDiagnostic(
                    GenerationSeverity.Warning,
                    $"Could not read members of '{type.FullName}': {ex.Message}"));
                interfaces[name] = $"export interface {name} {{\n  [key: string]: unknown;\n}}";
            }
        }

        var builder = new StringBuilder();
        builder.Append(Header);

        if (interfaces.Count == 0 && pages.Count == 0)
        {
            builder.Append("\n// No [InertiaPage] types were discovered.\n");
            return builder.ToString();
        }

        if (options.EmitReactHelper && pages.Count > 0)
        {
            AppendReactHelperImports(builder);
        }

        builder.Append('\n');
        bool first = true;
        foreach (string name in interfaces.Keys.OrderBy(static n => n, StringComparer.Ordinal))
        {
            if (!first)
            {
                builder.Append('\n');
            }

            builder.Append(interfaces[name]).Append('\n');
            first = false;
        }

        builder.Append('\n').Append(RenderPageRegistry(pages, resolver));

        if (options.EmitReactHelper && pages.Count > 0)
        {
            builder.Append("\n\n").Append(RenderReactHelper(sharedPropsType is not null));
        }

        return builder.ToString();
    }

    private static void AppendReactHelperImports(StringBuilder builder)
    {
        builder.Append('\n');
        builder.Append("import { usePage } from '@inertiajs/react';\n");
    }

    private static string RenderReactHelper(bool hasSharedProps)
    {
        string propsType = hasSharedProps
            ? "InertiaPageProps[K] & InertiaSharedProps"
            : "InertiaPageProps[K]";

        var builder = new StringBuilder();
        builder.Append("// Typed accessor for the props of a page component. The component name is\n");
        builder.Append("// only used to select the props type; props are read from the current page.\n");
        builder.Append("export function usePageProps<K extends keyof InertiaPageProps>(component: K): ")
            .Append(propsType).Append(" {\n");
        builder.Append("  void component;\n");
        builder.Append("  return usePage().props as ").Append(propsType).Append(";\n");
        builder.Append('}');
        return builder.ToString();
    }

    private static string RenderPageRegistry(IReadOnlyList<PageEntry> pages, TypeNameResolver resolver)
    {
        var builder = new StringBuilder();
        builder.Append("export interface InertiaPageProps {\n");

        foreach (PageEntry page in pages.OrderBy(static p => p.Component, StringComparer.Ordinal))
        {
            string component = page.Component.Replace("'", "\\'");
            builder.Append("  '").Append(component).Append("': ")
                .Append(resolver.Reserve(page.Type)).Append(";\n");
        }

        builder.Append('}');
        return builder.ToString();
    }

    private static IReadOnlyList<PageEntry> DiscoverPages(Assembly assembly)
    {
        var pages = new List<PageEntry>();

        foreach (Type type in EnumerateTypes(assembly))
        {
            IReadOnlyList<CustomAttributeData> attributes = MetadataHelpers.GetAttributes(type);
            foreach (CustomAttributeData attribute in attributes)
            {
                if (attribute.AttributeType.FullName != MetadataHelpers.InertiaPageAttribute)
                {
                    continue;
                }

                string? component = MetadataHelpers.GetStringArgument(attribute);
                if (!string.IsNullOrEmpty(component))
                {
                    pages.Add(new PageEntry(component!, type));
                }
            }
        }

        return pages;
    }

    /// <summary>
    /// Finds the single type marked with <c>[InertiaSharedProps]</c>. When more than one
    /// type is annotated a warning is reported and the first by full name is used so the
    /// output stays deterministic.
    /// </summary>
    private static Type? DiscoverSharedProps(Assembly assembly, List<GenerationDiagnostic> diagnostics)
    {
        var matches = new List<Type>();

        foreach (Type type in EnumerateTypes(assembly))
        {
            IReadOnlyList<CustomAttributeData> attributes = MetadataHelpers.GetAttributes(type);
            if (MetadataHelpers.HasAttribute(attributes, MetadataHelpers.InertiaSharedPropsAttribute))
            {
                matches.Add(type);
            }
        }

        if (matches.Count == 0)
        {
            return null;
        }

        Type selected = matches.OrderBy(FullNameOf, StringComparer.Ordinal).First();
        if (matches.Count > 1)
        {
            diagnostics.Add(new GenerationDiagnostic(
                GenerationSeverity.Warning,
                $"Multiple [InertiaSharedProps] types were found; using '{selected.FullName}'. " +
                "Only one shared props record is supported."));
        }

        return selected;
    }

    private static IEnumerable<Type> EnumerateTypes(Assembly assembly)
    {
        Type[] types;
        try
        {
            types = assembly.GetTypes();
        }
        catch (ReflectionTypeLoadException ex)
        {
            types = ex.Types.Where(static t => t is not null).Cast<Type>().ToArray();
        }

        foreach (Type type in types)
        {
            if (type is not null)
            {
                yield return type;
            }
        }
    }

    private static List<string> BuildResolverPaths(string assemblyPath, IList<string> referencePaths)
    {
        var byFileName = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var ordered = new List<string>();

        void Add(string path)
        {
            if (!File.Exists(path))
            {
                return;
            }

            string key = Path.GetFileName(path);
            if (byFileName.ContainsKey(key))
            {
                return;
            }

            byFileName[key] = path;
            ordered.Add(path);
        }

        Add(assemblyPath);

        string? directory = Path.GetDirectoryName(assemblyPath);
        if (!string.IsNullOrEmpty(directory))
        {
            foreach (string dll in Directory.GetFiles(directory, "*.dll"))
            {
                Add(dll);
            }
        }

        foreach (string reference in referencePaths)
        {
            Add(Path.GetFullPath(reference));
        }

        if (AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES") is string tpa)
        {
            foreach (string path in tpa.Split(Path.PathSeparator))
            {
                Add(path);
            }
        }

        AddSharedFrameworks(Add);

        return ordered;
    }

    /// <summary>
    /// Adds assemblies from the installed .NET shared frameworks (for example
    /// <c>Microsoft.AspNetCore.App</c>) so that references to framework types resolve
    /// even though the tool itself does not reference them.
    /// </summary>
    private static void AddSharedFrameworks(Action<string> add)
    {
        string runtimeDirectory = Path.GetDirectoryName(typeof(object).Assembly.Location) ?? string.Empty;
        string? sharedRoot = Path.GetDirectoryName(Path.GetDirectoryName(runtimeDirectory));
        if (string.IsNullOrEmpty(sharedRoot) || !Directory.Exists(sharedRoot))
        {
            return;
        }

        foreach (string frameworkDirectory in Directory.GetDirectories(sharedRoot).OrderBy(static d => d, StringComparer.Ordinal))
        {
            foreach (string versionDirectory in Directory.GetDirectories(frameworkDirectory).OrderByDescending(static d => d, StringComparer.Ordinal))
            {
                foreach (string dll in Directory.GetFiles(versionDirectory, "*.dll"))
                {
                    add(dll);
                }
            }
        }
    }

    private static string FullNameOf(Type type) => type.FullName ?? type.AssemblyQualifiedName ?? type.Name;

    private sealed record PageEntry(string Component, Type Type);
}
